import{t as e}from"./utils-COoNfFoj.js";var t={slug:`trace-young`,influencerName:`Trace Young`,influencerHandle:`@trace.young`,influencerAvatarUrl:`${e}/trace-young-avatar.png`,heroDescription:`The 99 Network sits at the intersection of athletes, schools, and brands, and that complexity was spread across too many tools to operate against effectively. I built this internal OS on Perplexity Computer so NIL budgets, athlete pipelines, brand matches, and campus execution all run from one command center, turning a messy market into a system we can scale.`,assetTitle:`Internal operating system`,screenshotUrl:`${e}/trace-young.png`,remixUrl:`https://www.perplexity.ai/computer/a/the-99-network-os-replica-GIExTRF0Q16esZaA5tu7Gw`,promptTitle:`Try Trace's Prompt`,promptText:`Build an external-facing, interactive dashboard that mimics an internal operating system for my business, using sample data so anyone can plug in their own. Match my brand colors and visual style, and include modular sections for pipeline, key accounts, growth metrics, and task status, with subtle motion and a futuristic feel. Make it feel operational and proactive — not a generic template — with realistic but illustrative numbers.`};export{t as default};
